    function getCellValue(coord) {
        const cell = document.querySelector(`[data-cell="${coord}"]`);
        if (cell && !isNaN(parseFloat(cell.textContent))) {
            return parseFloat(cell.textContent);
        }
        // Intentar si el contenido es simplemente un número sin formato de celda
         if (!cell) return null;

        const textContent = cell.textContent.trim();
        if (textContent && !isNaN(parseFloat(textContent))) {
             return parseFloat(textContent);
        }
        return null;
    }

    /**
     * Evalúa una fórmula dada su cadena de texto (Ej: "=SUMA(A1:A3)").
     * @param {string} formula - La fórmula a evaluar.
     * @returns {number|null} El resultado numérico o null si falla la evaluación.
     */
    function calculateFormula(formula) {
        // 1. Limpiar el signo '=' inicial
        let cleanFormula = formula.trim();
        if (cleanFormula.startsWith('=')) {
            cleanFormula = cleanFormula.substring(1);
        }

        // Lógica específica para SUMA
        const sumMatch = cleanFormula.toUpperCase().match(/SUMA\((.*)\)/);
        if (!sumMatch) return null;

        let content = sumMatch[1].trim(); // Contenido dentro de los paréntesis

        let cellsToSum = [];

        // 2. Manejo de rangos (ej: A1:A3). Esto requiere asumir una estructura simple.
        if (content.includes(':')) {
            const parts = content.split(':').map(p => p.trim());

            if (parts.length === 2) {
                // Intentar extraer la columna y el rango de filas del primer y último elemento.
                let startCoordMatch = parts[0].match(/([A-Z]+)([1-9]\d*)/);
                let endCoordMatch = parts[1].match(/([A-Z]+)([1-9]\d*)/);

                if (startCoordMatch && endCoordMatch) {
                    const startCol = startCoordMatch[1];
                    const startRow = parseInt(startCoordMatch[2]);
                    const endCol = endCoordMatch[1];
                    const endRow = parseInt(endCoordMatch[2]);

                    // Simplificación: Asumir que la columna es constante si el rango se define por A1:A3.
                     if (startCol === endCol) { 
                        for (let r = startRow; r <= endRow; r++) {
                            const coord = `${startCol}${r}`;
                            const value = getCellValue(coord);
                            if (value !== null) cellsToSum.push(value);
                        }
                    } else {
                         // Si la columna cambia, sumamos solo los valores de las coordenadas extremas si son únicas o se requiere lógica matricial compleja que no está disponible aquí. 
                         // Para este fix, nos quedaremos con el caso simple: Columna constante y rango lineal.
                         return null; // Fallo en manejo de rangos multi-columna.
                    }
                }
            } else {
                 // Caso de celdas sueltas (A1;B2;C3) o separadas por comas/puntos.
                 const delimiters = [';', ','];
                 let coordsFound = [];

                 for(const d of delimiters) {
                     content.split(d).forEach(coordStr => {
                         const coord = coordStr.trim();
                         if (coord && !isNaN(parseFloat(coord))) {
                             // Si es un número, puede ser que el usuario lo haya escrito directamente sin referencia
                             cellsToSum.push(parseFloat(coord)); 
                         } else if (coord) {
                            // Asumiendo formato de coordenada A1, B2...
                            const value = getCellValue(coord);
                            if (value !== null) cellsToSum.push(value);
                        }
                     });
                 }
            }

        let sumResult = 0;
        for (const value of cellsToSum) {
            sumResult += value;
        }
        return parseFloat(sumResult.toFixed(2)); // Redondear a 2 decimales


    } else {
         // Si no es SUMA, fallamos por simplicidad y nos enfocamos en el requisito de la prueba (SUMA).
         return null;
    }

    // --- Inicio del listener blur ---
    dataCells.forEach(cell => {
        // Añadimos un listener 'blur' (cuando se pierde el foco) para simular la finalización de la edición.
        cell.addEventListener('blur', function() {
            let originalValue = this.textContent.trim();

            if (!originalValue) return; 

            // 1. Detectar si es una fórmula
            if (originalValue.startsWith('=')) {
                const result = calculateFormula(originalValue);

                if (result !== null && !isNaN(result)) {
                    // 2. Si se calcula un resultado, lo actualizamos en la celda.
                    this.textContent = result.toString();
                } else {
                    console.warn("Fallo al calcular la fórmula.", originalValue);
                }
            } 

            console.log(`Celda ${this.dataset.cell} perdió el foco. Valor actual: "${this.textContent}"`);
        });

        // Opcionalmente, un listener 'focus' para resaltar visualmente la celda al hacer clic (si se requiere).
        cell.addEventListener('focus', function() {
            this.classList.add('focused-cell'); // Asumiendo que styles.css tiene una clase .focused-cell
        });

    });
    // --- Fin del listener blur ---


    // Listener de click global (fuera del forEach)
    document.body.addEventListener('click', function(e) {
        if (!e.target.closest('[contenteditable="true"]')) {
            dataCells.forEach(c => c.classList.remove('focused-cell'));
        }
    });
}

// Función principal que arranca la aplicación
function startApp() {
    initializeCellEditing();
}

