function calculateFormula(cell) {
    let formula = cell.textContent.trim();

    // Expresión regular simple para encontrar funciones y argumentos (ej: SUMA(A1:A3))
    const regex = /(\w+)\(([^)]*)\)/g;

    // Función de reemplazo que maneja la evaluación dentro de los paréntesis
    let matchesFound = false;
    formula = formula.replace(regex, (match, funcName, args) => {
        matchesFound = true;

        // 1. Normalizar nombres de funciones a inglés para el cálculo interno si es necesario, o usar lógica específica.
        const functionMap = {
            'SUMA': 'SUM',
            'REST': 'SUBTRACT', // Aunque la prueba requiere signos, lo cubrimos por completitud
            'MULT': 'MULTIPLY',
            'DIV': 'DIVIDE'
        };

        let funcNameNormalized = funcName.toUpperCase();
        if (functionMap[funcName]) {
             funcNameNormalized = functionMap[funcName];
        } else if (!['SUMA'].includes(funcName)) {
             // Si la función no es reconocida, devolver el texto original para no romper.
             return match; 
        }

        let argsArray = [];
        const rangesAndCells = args.split(';'); // Separa argumentos por punto y coma (estilo español)

        for(const arg of rangesAndCells) {
            // Limpiar espacios en blanco al inicio/final de cada argumento
