body {
    font-family: Arial, sans-serif;
    padding: 20px;
}

#spreadsheet-container {
    max-width: 1200px;
    margin: 0 auto;
}

#spreadsheet-grid {
    border-collapse: collapse;
    table-layout: fixed;
}

/* Estilos de encabezados y cabeceras */
.col-header, .row-header {
    background-color: #f2f2f2;
    font-weight: bold;
    text-align: center;
    padding: 10px 5px;
    border: 1px solid #ccc;
}

/* Celdas de datos */
td {
    border: 1px solid #ccc;
    padding: 8px;
    min-width: 50px; /* Asegura un tamaño mínimo visible para las celdas */
    box-sizing: border-box;
}

/* Celda enfocada (al hacer click) */
.focused-cell {
    background-color: #e6f7ff; /* Azul claro */
    outline: 2px solid #3498db;
}

/* Estilo para el menú contextual de color */
#context-menu {
    padding: 10px;
    border-radius: 4px;
    width: auto; /* Ajusta el ancho al contenido */
    min-width: 250px;
}

.context-item, .context-separator {
    cursor: pointer;
    padding: 8px;
    display: block;
    border-bottom: 1px solid #eee;
}

.context-item:hover {
    background-color: #f0f0f0;
}
