    }

    // 3. Mostrar controles y habilitar acciones
    showColumnControls(columnLetter);
}

function showColumnControls(columnLetter) {
    const container = document.getElementById('column-controls');
    if (!container) return;

    container.innerHTML = `
        <button class="action-btn" onclick="clearColumn('${columnLetter}')">🗑️ Borrar Contenido</button>
        <button class="action-btn" onclick="setColorColumn('${columnLetter}')">🎨 Cambiar Color de Fondo</button>
        <button class="action-btn delete-col-btn" onclick="deleteColumn('${columnLetter}')">❌ Eliminar Columna ${columnLetter}</button>
    `;
}

function clearColumn(columnLetter) {
    const columnIndex = getColumnIndexFromLetter(columnLetter);
    if (columnIndex === -1) return;

    // Recorrer todas las filas de datos
    document.querySelectorAll('#spreadsheet-grid tbody tr').forEach(row => {
        const cells = row.querySelectorAll('td');
        if (cells[columnIndex]) {
            cells[columnIndex].textContent = '';
            cells[columnIndex].setAttribute('data-original-content', ''); // Limpiar datos ocultos si existen
        }
    });

    alert(`Columna ${columnLetter} vaciada exitosamente.`);
}

function setColorColumn(columnLetter) {
    const columnIndex = getColumnIndexFromLetter(columnLetter);
    if (columnIndex === -1) return;

    // Aplicar un fondo de color llamativo para indicar selección/cambio.
    document.querySelectorAll('#spreadsheet-grid tbody tr td:nth-child(${columnIndex + 2})').forEach(cell => {
        cell.style.backgroundColor = '#ffe0b2'; // Color naranja claro por ejemplo
    });

    alert(`Color de fondo aplicado a la columna ${columnLetter}.`);
}

function deleteColumn(columnLetter) {
    if (!confirm(`¿Está seguro que desea ELIMINAR completamente la Columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const columnIndex = getColumnIndexFromLetter(columnLetter);
    if (columnIndex === -1) return;

    // 1. Eliminar el TH de encabezado
    const headerCell = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerCell) {
        headerCell.remove();
    }

    // 2. Eliminar todas las TDs correspondientes del tbody
    document.querySelectorAll('#spreadsheet-grid tbody tr td:nth-child(' + (columnIndex + 2) + ')').forEach(cell => {
        cell.remove();
    });

    alert(`Columna ${columnLetter} eliminada exitosamente.`);
}

/**
 * Helper function to map column letter (A, B, ...) to 0-based index for DOM manipulation.
 * A -> 0, B -> 1, C -> 2, etc.
 */
function getColumnIndexFromLetter(letter) {
    const col = letter.toUpperCase();
    let index = 0;
    for (let i = 0; i < col.length; i++) {
        index = index * 26 + (col.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
    }
    // Since the first TH is empty and col-headers start at A, we adjust for the offset.
    return index - 1; 
}
