    box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

/* Estilos generales de la tabla */
#spreadsheet-grid {
    width: 100%;
    border-collapse: collapse; /* Hace que los bordes se junten */
    table-layout: fixed; /* Asegura distribución uniforme de las columnas */
}

/* Estilo para todas las celdas (<th> y <td>) */
#spreadsheet-grid th, #spreadsheet-grid td {
    border: 1px solid #ddd; /* Borde gris claro por defecto */
    padding: 8px 10px;
    height: 30px; /* Altura estándar de las filas para consistencia */
    box-sizing: border-box; /* Incluye padding y border en el ancho total */
    vertical-align: top;
}

/* Estilo específico para las celdas de encabezado de columna (A, B, C...) */
.col-header {
    background-color: #e9e9e9;
    font-weight: bold;
    text-align: center;
    width: 30px; /* Ancho fijo para las letras de la columna */
    cursor: pointer; /* Indica que es clickeable */
    user-select: none; /* Previene selección de texto al hacer clic */
}

/* Estilo específico cuando una columna está seleccionada */
.selected-column {
    background-color: #cce5ff !important; /* Azul claro visible para indicar selección */
    border-right: 2px solid royalblue !important;
}


/* Estilo específico para las celdas de encabezado de fila (1, 2, 3...) */
.row-header {
