    text-align: center;
}

/* Estilos para las celdas de datos (<td>) */
#spreadsheet-grid td {
    background-color: #ffffff;
    cursor: text; /* Indica que es editable */
}

/* Efecto visual al pasar el ratón por encima o al estar enfocado en una celda */
#spreadsheet-grid th:hover, 
#spreadsheet-grid td:hover {
    background-color: #f0f8ff; /* Azul muy claro de hover */
}

/* Estilo cuando la celda está siendo editada (focus) */
[contenteditable="true"]:focus {
