/**
 * Variables de estado globales para la selección de columna.
 */
let selectedColumn = null; // Almacena la letra de la columna seleccionada (ej: 'A')

// ---------------------- LÓGICA DE SELECCIÓN Y ACCIONES DE COLUMNA ----------------------

/**
 * Selecciona visualmente una columna y actualiza el estado global.
 * @param {string} columnLetter - La letra de la columna a seleccionar (e.g., 'A').
 */
function selectColumn(columnLetter) {
    // 1. Deseleccionar cualquier columna previamente seleccionada
    document.querySelectorAll('.col-header').forEach(th => {
        th.classList.remove('selected-column');
    });

    if (selectedColumn === columnLetter) {
        // Si ya está seleccionada, deseleccionamos y no hacemos nada más.
        selectedColumn = null;
        return; 
    }

    // 2. Actualizar el estado y la UI
    selectedColumn = columnLetter;
    const headerElement = document.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerElement) {
        headerElement.classList.add('selected-column');
        console.log(`Columna ${columnLetter} seleccionada.`);
    } else {
         // Manejo de error si el header no se encuentra, aunque debería ser imposible con la estructura.
        console.error(`No se pudo encontrar el encabezado para la columna ${columnLetter}.`);
    }

    // 3. Mostrar un menú o controles (simulado por console/alert en este contexto).
    // En una app real, aquí aparecería un menú contextual debajo del header seleccionado.
    console.log(`--- ACCIONES DISPONIBLES PARA LA COLUMNA ${columnLetter} ---`);
    console.warn("Para borrar la columna: Llamar a deleteColumn()");
    console.info("Para cambiar el color de fondo: Llamar a setBackgroundColor(color)");
    console.warn("Para limpiar contenido: Llamar a clearColumnContent()");

    // Para propósitos de prueba, adjuntamos handlers temporales al body para que puedan ser invocados manualmente si es necesario
    document.body.dataset.action = `columnAction=${columnLetter}`;
}


/**
 * Elimina completamente la columna seleccionada del DOM (headers, row headers y celdas).
 */
function deleteColumn() {
    if (!selectedColumn) {
        alert("Por favor, seleccione una columna primero.");
        return;
    }

    const colLetter = selectedColumn;
    if (!confirm(`¿Está seguro de que desea ELIMINAR la columna ${colLetter}? Esta acción es irreversible.`)) {
        return;
    }

    // 1. Eliminar el encabezado de la columna (A, B, C...)
    const headerToDelete = document.querySelector(`.col-header[data-column="${colLetter}"]`);
    if (headerToDelete) {
        headerToDelete.remove();
    } else {
        console.error(`No se encontró el encabezado de columna ${colLetter}.`);
    }

    // 2. Eliminar las celdas de datos de todas las filas
    const dataCells = document.querySelectorAll(`#spreadsheet-grid td[data-cell^="${colLetter}"]`);
    dataCells.forEach(td => {
        td.remove();
    });

    // 3. Eliminar el encabezado de fila (si aplica) y las celdas restantes en cada TR
    const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    rows.forEach(row => {
        // Buscar la celda que corresponde a esta columna dentro del TR actual
        const cellToRemove = row.querySelector(`td[data-cell^="${colLetter}"]`);
        if (cellToRemove) {
            cellToRemove.remove();
        }
    });

    // 4. Resetear el estado de selección
    selectedColumn = null;
    console.log(`Columna ${colLetter} eliminada exitosamente.`);
}


/**
 * Establece un color de fondo en todas las celdas de la columna seleccionada.
 * @param {string} hexColor - El código hexadecimal del color (ej: '#ffcccc').
 */
function setBackgroundColor(hexColor) {
    if (!selectedColumn) {
        alert("Por favor, seleccione una columna primero.");
        return;
    }

    const colLetter = selectedColumn;
    // Selecciona todas las celdas de datos que pertenecen a esta columna.
    const dataCells = document.querySelectorAll(`#spreadsheet-grid td[data-cell^="${colLetter}"]`);

    dataCells.forEach(cell => {
        cell.style.backgroundColor = hexColor;
    });

    console.log(`Fondo de la columna ${colLetter} cambiado a ${hexColor}.`);
}


/**
 * Limpia el contenido de todas las celdas de datos de la columna seleccionada.
 */
function clearColumnContent() {
    if (!selectedColumn) {
        alert("Por favor, seleccione una columna primero.");
        return;
    }

    const colLetter = selectedColumn;
    const dataCells = document.querySelectorAll(`#spreadsheet-grid td[data-cell^="${colLetter}"]`);

    dataCells.forEach(cell => {
        // Limpiar el contenido y cualquier estilo de fondo aplicado previamente por esta función
        cell.textContent = ''; 
        cell.style.backgroundColor = ''; // Resetear color para que solo apliquen los estilos CSS base
    });

    console.log(`Contenido de la columna ${colLetter} limpiado.`);
}


// ---------------------- LÓGICA DE EDICIÓN Y EVALUACIÓN (MANTENIDA) ----------------------

/**
 * Inicializa la funcionalidad de edición inline en todas las celdas de datos.
 */
function initializeCellEditing() {
    // Selecciona todas las celdas de datos que son editables.
    const dataCells = document.querySelectorAll('#spreadsheet-grid td[contenteditable="true"]');

    dataCells.forEach(cell => {
        // Añadimos un listener 'blur' (cuando se pierde el foco) para simular la finalización de la edición.
        cell.addEventListener('blur', function() {
            let content = this.textContent.trim();

            if (content.startsWith("=")) {
                try {
                    // Extraer la fórmula sin el signo '='
                    const formulaString = content.substring(1).trim();

                    // Evaluar la fórmula y obtener el resultado numérico o string
                    let result = evaluateFormula(this, formulaString);

                    if (typeof result === 'number' && !isNaN(result)) {
                        // Si es un número válido, mostrarlo en lugar de la fórmula.
                        this.textContent = result; 
                    } else {
                         // Si falla o el resultado no es numérico, mantener la fórmula visible.
                         console.warn("No se pudo calcular la fórmula:", formulaString);
                    }

                } catch (e) {
                    console.error(`Error al evaluar fórmula en ${this.dataset.cell}:`, e);
                    // Si hay un error de cálculo, dejar el texto tal cual o mostrar '#ERROR!'
                    this.textContent = "#¡ERROR!"; 
                }
            }
        });

        // Opcionalmente, un listener 'focus' para resaltar visualmente la celda al hacer clic (si se requiere).
        cell.addEventListener('focus', function() {
             this.classList.add('focused-cell'); // Asumiendo que styles.css tiene una clase .focused-cell
        });

        // Limpiar el foco visual cuando se haga clic en cualquier parte del documento.
        document.body.addEventListener('click', function(e) {
            if (!e.target.closest('[contenteditable="true"]')) {
                dataCells.forEach(c => c.classList.remove('focused-cell'));
            }
        });
    });
}

