/**
 * Maneja el evento de clic en los encabezados de columna (letras).
 * Actualiza la UI para mostrar los controles de acción disponibles.
 * @param {HTMLElement} headerElement - El elemento <th> de la letra de columna clickeado.
 */
function selectColumnHandler(headerElement) {
    const columnIndex = parseInt(headerElement.dataset.columnIndex);
    const columnLetter = headerElement.textContent;

    // 1. Actualizar estado global y UI
    document.getElementById('selected-column-letter').textContent = columnLetter;
    document.getElementById('column-controls').classList.remove('hidden');

    // Guardar el índice de la columna seleccionada en un atributo o variable temporal si es necesario, 
    // pero por ahora confiaremos en el elemento DOM para referenciarla.
    const grid = document.getElementById('spreadsheet-grid');
    const headerRowCells = grid.querySelector('thead tr').querySelectorAll('.col-header');

    if (columnIndex >= 0 && columnIndex < headerRowCells.length) {
        // Marcar visualmente la columna activa si es necesario, aunque no se pidió.
        headerRowCells.forEach(el => el.classList.remove('active-column'));
        headerElement.classList.add('active-column');
    }

    // 2. Adjuntar listeners a los nuevos controles de acción
    setupColumnActionListeners();
}
