### FUNCION: setupColumnActionListeners
```js
/**
 * Configura los event listeners para los botones de acción de columna (Borrar, Color, Eliminar).
 */
function setupColumnActionListeners() {
    // Limpiar listeners anteriores si se vuelve a seleccionar una columna.
    document.getElementById('clear-col-btn').onclick = null;
    document.getElementById('color-col-btn').onclick = null;
    document.getElementById('delete-col-btn').onclick = null;

    const selectedHeaderElement = document.querySelector('.col-header.active-column');
    if (!selectedHeaderElement) {
        console.error("No hay columna seleccionada para configurar acciones.");
        return;
    }

    // Obtener el índice de la columna activa
    const columnIndex = parseInt(selectedHeaderElement.dataset.columnIndex);

    // 1. Listener para Borrar Contenido
    document.getElementById('clear-col-btn').onclick = () => {
        if (confirm(`¿Está seguro que desea borrar TODO el contenido de la columna ${selectedHeaderElement.textContent}?`)) {
            const columnCells = document.querySelectorAll(`#spreadsheet-grid td[data-column-index="${columnIndex}"]`);
            columnCells.forEach(cell => {
                cell.textContent = '';
                cell.style.backgroundColor = ''; // Asegurarse de limpiar el color también
            });
        }
    };

    // 2. Listener para Color de Fondo
    document.getElementById('color-col-btn').onclick = () => {
         if (confirm(`¿Está seguro que desea aplicar un fondo amarillo a TODA la columna ${selectedHeaderElement.textContent}?`)) {
            const columnCells = document.querySelectorAll(`#spreadsheet-grid td[data-column-index="${columnIndex}"]`);
            columnCells.forEach(cell => {
                cell.style.backgroundColor = '#ffffcc'; // Color claro amarillo
            });
        }
    };

    // 3. Listener para Eliminar Columna (Esta es la más compleja)
    document.getElementById('delete-col-btn').onclick = () => {
        if (!confirm(`¡PELIGRO! ¿Está seguro que desea ELIMINAR permanentemente la columna ${selectedHeaderElement.textContent}? Esta acción no se puede deshacer.`)) {
            return;
        }

        const columnIndex = parseInt(selectedHeaderElement.dataset.columnIndex);
        const grid = document.getElementById('spreadsheet-grid');

        // 1. Eliminar los TH de encabezado (la letra)
        const headerCellToDelete = selectedHeaderElement;
        if (headerCellToDelete && headerCellToDelete.parentNode) {
            headerCellToDelete.parentNode.removeChild(headerCellToDelete);
        }

        // 2. Identificar y eliminar todas las celdas de datos en esa columna
        const cellsToDelete = document.querySelectorAll(`#spreadsheet-grid td[data-column-index="${columnIndex}"]`);

        // Iterar hacia atrás para evitar problemas de índice DOM al eliminar elementos
        cellsToDelete.forEach(cell => {
            if (cell.parentNode) {
                cell.parentNode.removeChild(cell);
            }
        });

        // 3. Ajustar los índices de data-column-index en el resto del grid para mantener la integridad
        const allRemainingCells = document.querySelectorAll('#spreadsheet-grid td');
        allRemainingCells.forEach(cell => {
             let currentIndex = parseInt(cell.dataset.columnIndex);
             if (currentIndex > columnIndex) {
                cell.dataset.columnIndex = String(currentIndex - 1);
            }
        });

        // 4. Reajustar los encabezados y atributos de data-column-index en todo el THAD para que coincidan con la nueva estructura
        const allHeaders = document.querySelectorAll('#spreadsheet-grid th');
        allHeaders.forEach(header => {
            if (header.classList.contains('col-header')) {
                let currentLetterIndex = parseInt(header.dataset.columnIndex);
                if (currentLetterIndex > columnIndex) {
                    header.dataset.columnIndex = String(currentLetterIndex - 1);
                }
            }
        });

        // 5. Limpiar la selección de columna y reiniciar los controles visuales
        document.getElementById('column-controls').classList.add('hidden');
        document.querySelectorAll('.col-header').forEach(el => el.classList.remove('active-column'));
    };
}
