### FUNCION: handleColumnSelectionAndActions
```js
/**
 * Maneja el clic en los encabezados de columna para mostrar el menú contextual
 * y aplicar acciones como borrar contenido, cambiar color o eliminar la columna.
 * @param {HTMLElement} e - El evento de clic.
 */
function handleColumnSelectionAndActions(e) {
    const clickedHeader = e.target.closest('.col-header');
    if (!clickedHeader) return;

    // 1. Mostrar el menú contextual y determinar la columna seleccionada
    const columnLetter = clickedHeader.dataset.column;
    const menu = document.getElementById('column-context-menu');
    const letterDisplay = document.getElementById('selected-column-letter');

    if (menu) {
        // Posicionar el menú justo al lado del encabezado clicado
        const rect = clickedHeader.getBoundingClientRect();
        menu.style.top = `${rect.top - 10}px`; // Ajustar por padding/margen
        menu.style.left = `${rect.right + 15}px`;
        menu.classList.remove('hidden');

        letterDisplay.textContent = columnLetter;
    }


    // 2. Añadir event listeners de acción al menú (solo si no están ya añadidos)
    // Limpiamos listeners anteriores para evitar múltiples bindings
    document.getElementById('btn-clear-content').onclick = () => clearColumnContent(columnLetter);
    document.getElementById('btn-set-background-color').onclick = () => applyBackgroundColor(columnLetter, document.getElementById('color-picker').value);
    document.getElementById('btn-delete-column').onclick = () => deleteColumn(columnLetter);


    // 3. Agregar listeners de cierre global (click fuera del menú)
    const hideMenu = (e) => {
        if (!menu.contains(e.target) && e.target !== clickedHeader) {
            menu.classList.add('hidden');
            document.removeEventListener('click', hideMenu); // Limpiar listener después de usarlo
        }
    };
    document.addEventListener('click', hideMenu);

    // 4. Manejar el caso de click en un encabezado (mostrar menú)
    // Ya se manejó la visualización, solo necesitamos asegurar que los listeners estén activos.
}

/**
 * Obtiene todas las celdas de datos para una columna dada y ejecuta la acción.
 * @param {string} columnLetter - La letra de la columna (A, B, C...).
 * @returns {HTMLElement[]} Array de elementos TD en esa columna.
 */
function getColumnCells(columnLetter) {
    const allRows = document.querySelectorAll('#spreadsheet-grid tbody tr');
    let cells = [];

    // Calcular el índice basado en la letra (A=0, B=1...)
    let colIndex = 0;
    for (let i = 0; i < columnLetter.length; i++) {
        colIndex += (columnLetter.charCodeAt(i) - 'A'.charCodeAt(0));
    }

    allRows.forEach(row => {
        // Los TDs de datos comienzan después del TH de encabezado (índice 1 en el TR).
        const tds = row.querySelectorAll('td');
        if (tds[colIndex]) {
            cells.push(tds[colIndex]);
        }
    });
    return cells;
}

/**
 * Borra todo el contenido de una columna y limpia los estilos de fondo.
 * @param {string} columnLetter - La letra de la columna a limpiar.
 */
function clearColumnContent(columnLetter) {
    const cells = getColumnCells(columnLetter);
    cells.forEach(cell => {
        cell.textContent = '';
        // Resetear el color de fondo para que se vea limpio
        cell.style.backgroundColor = ''; 
    });
}

/**
 * Establece un color de fondo en todas las celdas de una columna.
 * @param {string} columnLetter - La letra de la columna.
 * @param {string} color - El código hexadecimal del color (#rrggbb).
 */
function applyBackgroundColor(columnLetter, color) {
    const cells = getColumnCells(columnLetter);
    cells.forEach(cell => {
        cell.style.backgroundColor = color;
    });
}

/**
 * Elimina completamente la columna de la tabla y actualiza los contenidos visuales.
 * @param {string} columnLetter - La letra de la columna a eliminar.
 */
function deleteColumn(columnLetter) {
    if (!confirm(`¿Está seguro que desea ELIMINAR permanentemente la columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const columnHeaders = document.getElementById('column-headers');
    // 1. Eliminar el TH del encabezado de columna
    const headerTh = columnHeaders.querySelector(`.col-header[data-column="${columnLetter}"]`);
    if (headerTh) {
        headerTh.remove();
    }

    // 2. Eliminar todas las celdas TD correspondientes en el tbody
    document.querySelectorAll(`td[data-cell^="${columnLetter}"]`).forEach(cell => {
        cell.remove();
    });

    // 3. Actualizar la interfaz de usuario (opcional: resetear menú)
    document.getElementById('column-context-menu').classList.add('hidden');
}
