function setupColumnSelectionListeners() {
    const colHeaders = document.querySelectorAll('.col-header');
    const selectedColNameSpan = document.getElementById('selected-column-name');

    // Limpiar la selección visual previa al iniciar
    document.body.addEventListener('click', function(e) {
        if (!e.target.closest('[contenteditable="true"]')) {
            // Remover clase de selección de todos los headers
            colHeaders.forEach(th => th.classList.remove('selected'));
            // Resetear el estado interno y visual
            document.getElementById('column-bg-color-picker').value = '#ffffff';
            selectedColNameSpan.textContent = 'Ninguna';
        }
    });

    colHeaders.forEach(header => {
        header.addEventListener('click', function() {
            // 1. Deseleccionar todos los demás headers
            colHeaders.forEach(th => th.classList.remove('selected'));

            // 2. Seleccionar el actual
            this.classList.add('selected');

            const columnName = this.dataset.column;
            if (columnName) {
                // Actualizar los controles de UI
                document.getElementById('selected-column-name').textContent = columnName;
                // Resetear y establecer color por defecto en el picker
                document.getElementById('column-bg-color-picker').value = '#ffffff'; 
            } else {
                 document.getElementById('selected-column-name').textContent = 'Ninguna';
            }
        });
    });
}

/**
 * Aplica la acción de cambiar el color de fondo a todas las celdas de una columna seleccionada.
 * @param {string} color - El código hexadecimal del color (#RRGGBB).
 */
function changeColumnBackgroundColor(color) {
    const selectedHeader = document.querySelector('.col-header.selected');
    if (!selectedHeader) return;

    const columnName = selectedHeader.dataset.column;
    if (!columnName) return;

    // 1. Encontrar la columna (incluyendo el TH de encabezado)
    const columnCells = document.querySelectorAll(`#spreadsheet-grid th[data-column="${columnName}"], #spreadsheet-grid td[data-column="${columnName}"]`);

    if (columnCells.length === 0) {
        console.error(`No se encontraron celdas para la columna ${columnName}.`);
        return;
    }

    // 2. Aplicar el estilo a todas las celdas de datos y al header
    columnCells.forEach(cell => {
        // Solo aplicamos color de fondo a los TDs que son contenido editable, y también al TH si es necesario para consistencia visual.
        if (cell.tagName === 'TD' && cell.hasAttribute('contenteditable')) {
            cell.style.backgroundColor = color;
        } else if (cell.tagName === 'TH') {
             // Aplicar a la celda de encabezado si es el elemento seleccionado
             if(cell.dataset.column === columnName) {
                 cell.style.backgroundColor = color;
             }
        }
    });
}

/**
 * Limpia el contenido de todas las celdas de una columna seleccionada, manteniendo la estructura.
 */
function clearSelectedColumnContent() {
    const selectedHeader = document.querySelector('.col-header.selected');
    if (!selectedHeader) return;

    const columnName = selectedHeader.dataset.column;
    if (!columnName) return;

    // Seleccionar todos los TDs de la columna, excluyendo el header (que ya está limpio).
    const columnDataCells = document.querySelectorAll(`#spreadsheet-grid td[data-column="${columnName}"]`);

    columnDataCells.forEach(cell => {
        cell.textContent = '';
        // Opcionalmente resetear estilos si la limpieza implica borrar el color aplicado por usuario
        cell.style.backgroundColor = ''; 
    });
}

/**
 * Elimina completamente una columna de la grilla, incluyendo su header y todos los datos asociados.
 */
function deleteSelectedColumn() {
    const selectedHeader = document.querySelector('.col-header.selected');
    if (!selectedHeader) {
        alert("Por favor, selecciona una columna para eliminar.");
        return;
    }

    if (!confirm(`¿Estás seguro de que quieres ELIMINAR la columna ${selectedHeader.dataset.column}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const columnName = selectedHeader.dataset.column;

    // 1. Eliminar todas las celdas TD de esa columna en el tbody.
    const cellsToDelete = document.querySelectorAll(`#spreadsheet-grid td[data-column="${columnName}"]`);
    cellsToDelete.forEach(cell => cell.remove());

    // 2. Eliminar el header TH de la columna.
    selectedHeader.remove();

    // 3. Resetear la selección visual y los controles.
    const colHeaders = document.querySelectorAll('.col-header');
    colHeaders.forEach(th => th.classList.remove('selected'));
    document.getElementById('column-bg-color-picker').value = '#ffffff';
    document.getElementById('selected-column-name').textContent = 'Ninguna';

    console.log(`Columna ${columnName} eliminada exitosamente.`);
}
