### FUNCION: setupColumnSelectionListeners
```js
function setupColumnSelectionListeners() {
    const colHeaders = document.querySelectorAll('.col-header');
    const controlsContainer = document.getElementById('column-controls');
    let selectedColumn = null;

    // Limpiar y configurar el contenedor de controles al inicio
    if (controlsContainer) {
        controlsContainer.innerHTML = '';
        controlsContainer.style.display = 'none';
    }

    // Event listener para manejar la selección global y ocultar los controles si se hace clic fuera
    document.addEventListener('click', function(e) {
        const controls = document.getElementById('column-controls');
        if (!e.target.closest('.col-header') && !e.target.closest('#column-controls')) {
            // Si el clic no fue en un encabezado ni en los controles, deseleccionar y ocultar
            selectColumn(null);
        }
    });

    // Listener para cada encabezado de columna
    colHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const columnName = this.dataset.column;
            selectColumn(columnName, this);
        });
    });

    /**
     * Selecciona visualmente la columna y muestra los controles de acción.
     * @param {string} columnName - La letra de la columna seleccionada (A, B, C...).
     * @param {HTMLElement} headerElement - El elemento <th> que fue clicado.
     */
    function selectColumn(columnName, headerElement) {
        // Deseleccionar previamente cualquier columna
        if (selectedColumn) {
            const prevHeader = document.querySelector('.col-header.selected');
            if (prevHeader) {
                prevHeader.classList.remove('selected');
            }
        }

        selectedColumn = columnName;

        // Seleccionar el nuevo encabezado y marcarlo visualmente
        if (headerElement) {
             headerElement.classList.add('selected');
        } else if (columnName) {
            const newHeader = document.querySelector(`.col-header[data-column="${columnName}"]`);
            if(newHeader) {
                newHeader.classList.add('selected');
            }
        }

        // Mostrar y poblar los controles de acción
        const controlsContainer = document.getElementById('column-controls');
        if (controlsContainer) {
            controlsContainer.style.display = 'block';
            controlsContainer.innerHTML = `
                <div class="control-group">
                    <label for="bg-color-picker">Color de Fondo:</label>
                    <input type="color" id="bg-color-picker" value="#ffffff">
                    <button id="set-background-btn">Aplicar Color</button>
                </div>
                <div class="control-group">
                    <button id="clear-column-btn">Borrar Contenido de Columna</button>
                    <button id="delete-column-btn" class="danger">Eliminar Columna Completa</button>
                </div>
            `;

            // Añadir listeners a los nuevos botones/inputs
            document.getElementById('set-background-btn').onclick = () => {
                const color = document.getElementById('bg-color-picker').value;
                setBackgroundColor(color, columnName);
            };

            document.getElementById('clear-column-btn').onclick = () => {
                clearColumn(columnName);
            };

             // Confirmación antes de borrar una columna completa
            document.getElementById('delete-column-btn').onclick = () => {
                if (confirm(`¿Está seguro de que desea eliminar la Columna ${columnName}? Esta acción es irreversible.`)) {
                    deleteColumn(columnName);
                }
            };
        }
    }

    /**
     * Cambia el color de fondo de todas las celdas en la columna dada.
     * @param {string} columnName - La letra de la columna (A, B...).
     * @param {string} color - El código hexadecimal del color (#RRGGBB).
     */
    function setBackgroundColor(columnName, color) {
        const cells = document.querySelectorAll(`#spreadsheet-grid td[data-cell^="${columnName}"]`);
        cells.forEach(cell => {
            cell.style.backgroundColor = color;
        });
    }

    /**
     * Borra el contenido de todas las celdas en la columna dada, manteniendo su estructura.
     * @param {string} columnName - La letra de la columna (A, B...).
     */
    function clearColumn(columnName) {
        const cells = document.querySelectorAll(`#spreadsheet-grid td[data-cell^="${columnName}"]`);
        cells.forEach(cell => {
            cell.textContent = '';
            // También limpiamos el color de fondo al borrar contenido, para que no quede un color residual.
            cell.style.backgroundColor = ''; 
        });
    }

    /**
     * Elimina completamente la columna (header y todas las celdas).
     * @param {string} columnName - La letra de la columna a eliminar.
     */
    function deleteColumn(columnName) {
        // 1. Remover el TH del encabezado
        const headerToRemove = document.querySelector(`.col-header[data-column="${columnName}"]`);
        if (headerToRemove) {
            headerToRemove.remove();
        }

        // 2. Iterar sobre las filas de datos y remover la TD correspondiente.
        const rows = document.querySelectorAll('#spreadsheet-grid tbody tr');
        rows.forEach(row => {
            // Buscamos el índice del TH que se acaba de eliminar (si es A, buscamos el 0).
            let columnIndex = 1; // Empezamos en el primer TD después del row header.
            const tds = row.querySelectorAll('td');

            // Esto es un poco complicado porque necesitamos saber qué TD corresponde a la columna 'A' si esta se elimina.
            // Dado que los TDs están en orden A, B, C..., podemos usar el índice de la columna.
            // Si eliminamos la columna X (ej: A), y queremos eliminar la celda correspondiente en todas las filas.

            let removed = false;
            for(let i=0; i < tds.length; i++) {
                // La primera columna de TD siempre es la que corresponde a 'A' si el header se eliminó correctamente.
                // Si A fue eliminado, queremos eliminar el primer td (índice 0) del TR.
                if (!removed && columnIndex === 1) { // Solo procesamos la eliminación una vez por fila para evitar dobles remociones
                    const cellToRemove = tds[i];
                     // Verificación extra: si esta celda está marcada como A* en su data-cell, entonces es la columna a borrar.
                    if (cellToRemove.dataset.cell && cellToRemove.dataset.cell.startsWith(columnName)) {
                        cellToRemove.remove();
                        removed = true;
                        break; // Solo hay una celda por fila para esa columna
                    }
                }
            }
        });

         // 3. Reindexar las columnas restantes (opcional, pero bueno para la usabilidad)
        updateColumnHeaders();
    }

    /**
     * Actualiza los índices de las celdas después de una eliminación.
     */
    function updateColumnHeaders() {
        const grid = document.getElementById('spreadsheet-grid');
        const allTds = grid.querySelectorAll('td');
        let currentColLetter = 'A';

        allTds.forEach(td => {
            // Esto es difícil de hacer perfectamente sin un sistema de coordenadas más robusto, 
            // pero al menos reasignamos los data-cell si la eliminación afectó el orden físico del DOM.
            const originalCell = td;
            let newColLetter = currentColLetter;

             // Si se eliminaron columnas, las celdas restantes deben mantener su data-cell correcto basado en el encabezado visible.
            if (originalCell.dataset.cell) {
                const match = originalCell.dataset.cell.match(/^([A-Z]+)([1-9]\d*)$/i);
                if(match) {
                    // Simplemente dejamos que la estructura HTML maneje el orden, ya que los headers se eliminaron y los TDs siguen en su posición relativa.
                    // Solo reasignamos data attributes si es necesario un reset total.
                }
            }

            currentColLetter = getNextColumnLetter(currentColLetter);
        });
    }

     /** Helper function to find the next column letter (A->B, Z->AA) */
    function getNextColumnLetter(letter) {
        let code = 0;
        for (let i = 0; i < letter.length; i++) {
            code = code * 26 + (letter.charCodeAt(i) - 'A'.charCodeAt(0) + 1);
        }

        let nextCode = code + 1;
        if (nextCode > Math.pow(26, letter.length)) {
             // Handle overflow to multi-character columns if necessary (e.g., AA, AB...)
             // Given the scope A-J, this is overkill but robust.
        }

        let nextLetter = '';
        while (nextCode > 0) {
            let charCode = (nextCode - 1) % 26;
            nextLetter = String.fromCharCode('A'.charCodeAt(0) + charCode) + nextLetter;
            nextCode = Math.floor((nextCode - 1) / 26);
        }
        return nextLetter;
    }
}
