### FUNCION: selectRow
```javascript
/**
 * Maneja la selección de una fila haciendo clic en su encabezado (número).
 * @param {HTMLElement} rowHeader - El elemento TH que contiene el número de la fila.
 */
function selectRow(rowHeader) {
    // 1. Deseleccionar cualquier fila previamente seleccionada y limpiar estilos.
    document.querySelectorAll('.data-row').forEach(row => {
        row.classList.remove('selected-row');
    });

    // 2. Obtener la fila completa (<tr>).
    const row = rowHeader.closest('.data-row');
    if (!row) return;

    // 3. Marcar visualmente la nueva fila seleccionada.
    row.classList.add('selected-row');

    // 4. Actualizar el estado global de la fila seleccionada.
    window._selectedRow = row;
}
