function initializeRowSelectionAndDeletion() {
    const rowHeaders = document.querySelectorAll('.row-header');
    const deleteButton = document.getElementById('clear-row-btn');
    let selectedRow = null;

    // Función para deseleccionar todas las filas
    const clearSelection = () => {
        document.querySelectorAll('.spreadsheet-row').forEach(row => {
            row.classList.remove('selected-row');
        });
        selectedRow = null;
        deleteButton.disabled = true;
    };

    // Listener para seleccionar la fila haciendo clic en el número de la fila (th.row-header)
    rowHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const rowElement = this.closest('.spreadsheet-row');
            if (!rowElement) return;

            // Deseleccionar cualquier otra fila y seleccionar esta
            clearSelection();
            selectedRow = rowElement;
            rowElement.classList.add('selected-row');
            deleteButton.disabled = false;
        });
    });

    // Listener para el botón de borrar la fila
    deleteButton.addEventListener('click', () => {
        if (selectedRow) {
            const rowToDelete = selectedRow;
            // Confirmación visual y funcional antes de eliminar
            if (confirm("¿Está seguro de que desea borrar esta fila completa? Esta acción no se puede deshacer.")) {
                rowToDelete.remove();
                clearSelection();
            }
        } else {
            alert('Por favor, seleccione una fila primero.');
        }
