let selectedRowElement = null;

/**
 * Ejecuta las acciones de la fila seleccionada (borrar, colorear o vaciar).
 * @param {string} action - 'delete', 'color', or 'clear'.
 * @param {string|null} [color=null] - Color hexadecimal si la acción es 'color'.
 */
function handleRowActions(action, color = null) {
    if (!selectedRowElement || selectedRowElement.tagName !== 'TR') {
        console.warn("No hay fila seleccionada para aplicar la acción.");
        return;
    }

    const cells = selectedRowElement.querySelectorAll('td[contenteditable="true"]');

    switch (action) {
        case 'delete':
            if (confirm("¿Está seguro de que desea borrar esta fila? Esta acción no se puede deshacer.")) {
                selectedRowElement.remove();
                // Limpiar selección después de la eliminación
                clearSelection();
                alert('Fila eliminada.');
            }
            break;
        case 'color':
            if (color) {
                cells.forEach(cell => {
                    cell.style.backgroundColor = color;
                });
                console.log(`Fondo de la fila coloreado con ${color}.`);
            }
            break;
        case 'clear':
            cells.forEach(cell => {
                cell.textContent = '';
                // Resetear fondo y estilo para simular un borrado limpio visualmente.
                cell.style.backgroundColor = ''; 
                cell.style.color = ''; // Asegurarse de que el color del texto también se resetea
            });
            console.log('Contenido de la fila vaciado exitosamente.');
            break;
    }
}

/**
 * Selecciona y resalta visualmente una fila específica.
 * @param {HTMLElement} rowElement - El elemento <tr> a seleccionar.
 */
function selectRow(rowElement) {
    // Deseleccionar cualquier otra fila previamente seleccionada
    document.querySelectorAll('.row-header').forEach(th => th.parentElement.classList.remove('selected-row'));

    if (rowElement && rowElement.tagName === 'TR') {
        rowElement.classList.add('selected-row');
        selectedRowElement = rowElement;
    } else {
        clearSelection();
    }
}

/**
 * Limpia la selección de fila activa.
 */
function clearSelection() {
    document.querySelectorAll('.row-header').forEach(th => th.parentElement.classList.remove('selected-row'));
    selectedRowElement = null;
}
