/* Estilos base de la hoja de cálculo */
body {
    font-family: Arial, sans-serif;
}

#spreadsheet-container {
    overflow-x: auto;
    padding: 20px;
    background-color: #f9f9f9;
    border: 1px solid #ccc;
    border-radius: 5px;
}

#spreadsheet-grid {
    width: fit-content; /* Permite que la tabla crezca con las columnas */
    border-collapse: collapse;
    table-layout: fixed; /* Asegura un ancho consistente */
}

/* Estilo de celdas y encabezados generales */
th, td {
    padding: 8px 10px;
    border: 1px solid #ddd;
    text-align: left;
    min-width: 50px; /* Ancho mínimo para evitar colapsar */
    box-sizing: border-box;
}

/* Encabezados de columna (A, B, C...) */
.col-header {
    background-color: #e6e6e6;
    font-weight: bold;
    text-align: center;
    width: 50px; /* Ancho fijo para la letra de la columna */
}

/* Encabezados de fila (1, 2, 3...) */
.row-header {
    background-color: #dcdcdc;
    font-weight: bold;
    text-align: center;
    width: 50px; /* Ancho fijo para el número de la fila */
}

/* Estilo para las celdas de datos editables */
[contenteditable="true"] {
    cursor: text;
    outline: none;
}

/* Resaltado al enfocar una celda */
.focused-cell {
    box-shadow: 0 0 3px rgba(0, 120, 255, 0.5);
    background-color: #eef7ff !important; /* Usamos !important para anular estilos de fondo */
}

/* Controles de ocultar y botones */
.hide-control {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 16px;
    padding: 0 5px;
    margin-left: 5px;
    color: #333;
    transition: color 0.2s;
}

.hide-control:hover {
    color: #cc0000; /* Color de alerta al pasar el ratón */
}

/* Estilos para ocultar elementos (usado por JS) */
.hidden-row, .hidden-column {
    display: none !important; 
}
