            this.classList.toggle('hidden-row');
            let isHidden = !this.classList.contains('hidden-row'); // True si acaba de ser ocultada


            // El elemento de la fila (TR) contiene tanto el TH del número como los TD de datos.
            const targetRow = this.closest('tr'); 

            if (!targetRow) {
                console.error("No se pudo encontrar la fila contenedora.");
                return;
            }

            // Seleccionar todas las celdas de datos (td) dentro de esta fila.
            const cellsToModify = targetRow.querySelectorAll('td[contenteditable="true"]');
            cellsToModify.forEach(cell => {
                cell.classList.toggle('hidden-row');
            });


            // 2. MANEJO DE BORRADO (Funcionalidad existente): Vaciar el contenido de la fila.
            const cellsToClear = targetRow.querySelectorAll('td[contenteditable="true"]');

            cellsToClear.forEach(cell => {
                cell.textContent = '';
                // Resetear el estilo de fondo
                cell.style.backgroundColor = ''; 
            });


            if (isHidden) {
                console.log(`Fila ${rowNum} oculta y vaciada.`);
            } else {
                console.log(`Fila ${rowNum} visible y vaciada.`);
            }
        });
